True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(vals, color):
        inds = [i for i, v in enumerate(vals) if v == color]
        if not inds:
            return []
        groups = []
        start = prev = inds[0]
        for i in inds[1:]:
            if i != prev + 1:
                groups.append((start, prev + 1))
                start = i
            prev = i
        groups.append((start, prev + 1))
        return groups

    # Find matching bars on opposing borders. Each bar is a contiguous run
    # of one non-background color along a border.
    bars = []
    for color in counts:
        if color == bg:
            continue
        top = runs(grid[0], color)
        bottom = runs(grid[-1], color)
        for a in top:
            for b in bottom:
                if a[1] - a[0] == b[1] - b[0]:
                    bars.append(("tb", color, a, b))
        left = runs([grid[r][0] for r in range(h)], color)
        right = runs([grid[r][-1] for r in range(h)], color)
        for a in left:
            for b in right:
                if a[1] - a[0] == b[1] - b[0]:
                    bars.append(("lr", color, a, b))
    if not bars:
        return out
    # ARC instances here contain a single pair of equal-length border bars.
    axis, bar_color, a, b = bars[0]

    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != bar_color]
    for r, c, color in points:
        if axis == "tb":
            coord = c
            # The point is aligned with the bar at its source edge.
            if a[0] <= coord < a[1]:
                src, dst, srcside, dstside = a, b, "top", "bottom"
            elif b[0] <= coord < b[1]:
                src, dst, srcside, dstside = b, a, "bottom", "top"
            else:
                continue
            newcoord = dst[0] + (coord - src[0])
            # Project the point back to the source bar, preserving the bar.
            if srcside == "top":
                for rr in range(1, r):
                    if out[rr][coord] == bg:
                        out[rr][coord] = color
            else:
                for rr in range(r + 1, h - 1):
                    if out[rr][coord] == bg:
                        out[rr][coord] = color
            # The translated point defines a complete perpendicular stripe.
            for rr in range(h):
                if out[rr][newcoord] == bg:
                    out[rr][newcoord] = color
        else:
            coord = r
            if a[0] <= coord < a[1]:
                src, dst, srcside, dstside = a, b, "left", "right"
            elif b[0] <= coord < b[1]:
                src, dst, srcside, dstside = b, a, "right", "left"
            else:
                continue
            newcoord = dst[0] + (coord - src[0])
            if srcside == "left":
                for cc in range(1, c):
                    if out[r][cc] == bg:
                        out[r][cc] = color
            else:
                for cc in range(c + 1, w - 1):
                    if out[r][cc] == bg:
                        out[r][cc] = color
            for cc in range(w):
                if out[newcoord][cc] == bg:
                    out[newcoord][cc] = color
        out[r][c] = 4
    return out
